SELECT
    id, name, main_image, category_id, merchant_id,
    price, original_price, stock, sold_count, view_count,
    status, is_recommended, create_time
FROM product


        merchant_id = #{merchantId}


        AND name LIKE CONCAT('%', #{name}, '%')


        AND category_id = #{categoryId}


        AND status = #{status}




        ORDER BY price ${sortOrder == 'asc' ? 'ASC' : 'DESC'}


        ORDER BY stock ${sortOrder == 'asc' ? 'ASC' : 'DESC'}


        ORDER BY sold_count ${sortOrder == 'asc' ? 'ASC' : 'DESC'}


        ORDER BY view_count ${sortOrder == 'asc' ? 'ASC' : 'DESC'}


        ORDER BY create_time DESC


LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM product


        merchant_id = #{merchantId}


        AND name LIKE CONCAT('%', #{name}, '%')


        AND category_id = #{categoryId}


        AND status = #{status}

SELECT *
FROM product
WHERE id = #{id} AND merchant_id = #{merchantId}

SELECT
    id, name, subtitle, main_image, price, stock, category_id,
    merchant_id, create_time, update_time
FROM product

    status = 2

        AND id = #{productId}


        AND name LIKE CONCAT('%', #{productName}, '%')


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM product

    status = 2

        AND id = #{productId}


        AND name LIKE CONCAT('%', #{productName}, '%')


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}

SELECT
    p.id, p.name, p.main_image, p.category_id, p.merchant_id,
    p.price, p.original_price, p.stock, p.sold_count, p.view_count,
    p.status, p.create_time, p.update_time
FROM product p
LEFT JOIN admin a ON p.merchant_id = a.id


        AND p.name LIKE CONCAT('%', #{productName}, '%')


        AND a.username LIKE CONCAT('%', #{merchantName}, '%')


        AND p.category_id = #{categoryId}


        AND p.status = #{status}


        AND p.create_time >= #{startTime}


        AND p.create_time <= #{endTime}




        ORDER BY p.price ${sortOrder == 'asc' ? 'ASC' : 'DESC'}


        ORDER BY p.stock ${sortOrder == 'asc' ? 'ASC' : 'DESC'}


        ORDER BY p.sold_count ${sortOrder == 'asc' ? 'ASC' : 'DESC'}


        ORDER BY p.view_count ${sortOrder == 'asc' ? 'ASC' : 'DESC'}


        ORDER BY p.create_time DESC


LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM product p
LEFT JOIN admin a ON p.merchant_id = a.id


        AND p.name LIKE CONCAT('%', #{productName}, '%')


        AND a.username LIKE CONCAT('%', #{merchantName}, '%')


        AND p.category_id = #{categoryId}


        AND p.status = #{status}


        AND p.create_time >= #{startTime}


        AND p.create_time <= #{endTime}
